import "server-only";
import Anthropic from "@anthropic-ai/sdk";
import type { SupabaseClient } from "@supabase/supabase-js";
import { env } from "./env";
import { dayBoundsUtc, shiftDate } from "./time";

/**
 * Weekly intelligence report. Metrics are computed from stored records only;
 * the optional narrative is generated by Claude from those metrics (with the
 * user's AI consent) and stored separately, labelled as interpretation.
 */

export interface WeeklyMetrics {
  period: { start: string; end: string };
  sample: Record<string, number>;
  commitments: { made: number; kept: number; kept_late: number; broken: number; released: number; unresolved: number; on_time_rate: number | null };
  tasks: { scheduled: number; done: number; done_with_evidence: number; missed: number; left_open: number; postponed: number };
  habits: { tracked: number; completions: number; target: number; consistency: number | null };
  prayer: { confirmed: number; possible: number; by_prayer: Record<string, number> };
  focus: { sessions: number; completed: number; minutes: number };
  impulses: { logged: number; resisted: number; by_kind: Record<string, number> };
  finance: { entries: number; days_with_entries: number; discretionary_total: number; spent_total: number };
  goals: { active: number; progress_entries: number };
  checkins: { morning: number; midday: number; evening: number; skipped_answers: number };
  journal: { entries: number; avg_mood: number | null; tags: Record<string, number> };
  distraction_reports: string[];
}

export interface Example { date: string; text: string; source: string }

export async function computeWeek(db: SupabaseClient, userId: string, start: string, tz: string) {
  const end = shiftDate(start, 6);
  const s = dayBoundsUtc(start, tz).start.toISOString();
  const e = dayBoundsUtc(end, tz).end.toISOString();
  const q = <T>(p: PromiseLike<{ data: T[] | null }>) => p.then((r) => r.data ?? []);
  const [cs, ts, hs, hl, pc, fs, im, fe, gp, ss, aa, je, goals] = await Promise.all([
    q(db.from("commitments").select("title,status,commitment_date,failure_context,evidence,verification").eq("user_id", userId).gte("commitment_date", start).lte("commitment_date", end)),
    q(db.from("tasks").select("title,status,scheduled_for,postponed_count,verification,miss_reason").eq("user_id", userId).gte("scheduled_for", start).lte("scheduled_for", end)),
    q(db.from("habits").select("id,title,target_per_week").eq("user_id", userId).eq("active", true)),
    q(db.from("habit_logs").select("habit_id,status,log_date").eq("user_id", userId).gte("log_date", start).lte("log_date", end)),
    q(db.from("prayer_confirmations").select("prayer,prayer_date").eq("user_id", userId).gte("prayer_date", start).lte("prayer_date", end)),
    q(db.from("focus_sessions").select("status,planned_minutes,started_at,intention").eq("user_id", userId).gte("started_at", s).lt("started_at", e)),
    q(db.from("impulse_logs").select("kind,outcome,created_at").eq("user_id", userId).gte("created_at", s).lt("created_at", e)),
    q(db.from("financial_entries").select("kind,amount,discretionary,entry_date").eq("user_id", userId).gte("entry_date", start).lte("entry_date", end)),
    q(db.from("goal_progress").select("id").eq("user_id", userId).gte("created_at", s).lt("created_at", e)),
    q(db.from("accountability_sessions").select("kind,status,session_date").eq("user_id", userId).gte("session_date", start).lte("session_date", end)),
    q(db.from("accountability_answers").select("question_key,answer,skipped,created_at").eq("user_id", userId).gte("created_at", s).lt("created_at", e)),
    q(db.from("journal_entries").select("mood,tags,entry_date").eq("user_id", userId).gte("entry_date", start).lte("entry_date", end)),
    q(db.from("goals").select("id").eq("user_id", userId).eq("status", "active")),
  ]);
  type C = { title: string; status: string; commitment_date: string; failure_context: string | null; evidence: string | null; verification: string };
  type T = { title: string; status: string; scheduled_for: string; postponed_count: number; verification: string; miss_reason: string | null };
  const C = cs as C[], Ts = ts as T[];
  const resolved = C.filter((c) => !["open", "released"].includes(c.status));
  const habitTarget = (hs as { target_per_week: number }[]).reduce((a, h) => a + h.target_per_week, 0);
  const habitDone = (hl as { status: string }[]).filter((l) => l.status === "done").length;
  const byPrayer: Record<string, number> = {};
  for (const p of pc as { prayer: string }[]) byPrayer[p.prayer] = (byPrayer[p.prayer] ?? 0) + 1;
  const byKind: Record<string, number> = {};
  for (const i of im as { kind: string }[]) byKind[i.kind] = (byKind[i.kind] ?? 0) + 1;
  const tags: Record<string, number> = {};
  for (const j of je as { tags: string[] }[]) for (const t of j.tags) tags[t] = (tags[t] ?? 0) + 1;
  const moods = (je as { mood: number | null }[]).map((j) => j.mood).filter((m): m is number => m != null);
  const sess = ss as { kind: string; status: string }[];
  const answers = aa as { question_key: string; answer: string; skipped: boolean }[];
  const fin = fe as { kind: string; amount: number; discretionary: boolean; entry_date: string }[];

  const metrics: WeeklyMetrics = {
    period: { start, end },
    sample: { commitments: C.length, tasks: Ts.length, habit_logs: hl.length, prayer_confirmations: pc.length, focus_sessions: fs.length, impulse_logs: im.length, financial_entries: fe.length, checkin_answers: aa.length, journal_entries: je.length },
    commitments: {
      made: C.length, kept: C.filter((c) => c.status === "kept").length, kept_late: C.filter((c) => c.status === "kept_late").length,
      broken: C.filter((c) => c.status === "broken").length, released: C.filter((c) => c.status === "released").length, unresolved: C.filter((c) => c.status === "open").length,
      on_time_rate: resolved.length ? Math.round((C.filter((c) => c.status === "kept").length / resolved.length) * 100) : null,
    },
    tasks: {
      scheduled: Ts.length, done: Ts.filter((t) => t.status === "done").length, done_with_evidence: Ts.filter((t) => t.status === "done" && t.verification === "evidence").length,
      missed: Ts.filter((t) => t.status === "missed").length, left_open: Ts.filter((t) => t.status === "pending").length, postponed: Ts.filter((t) => t.postponed_count > 0).length,
    },
    habits: { tracked: hs.length, completions: habitDone, target: habitTarget, consistency: habitTarget ? Math.round((habitDone / habitTarget) * 100) : null },
    prayer: { confirmed: pc.length, possible: 35, by_prayer: byPrayer },
    focus: { sessions: fs.length, completed: (fs as { status: string }[]).filter((f) => f.status === "completed").length, minutes: (fs as { status: string; planned_minutes: number }[]).filter((f) => f.status === "completed").reduce((a, f) => a + f.planned_minutes, 0) },
    impulses: { logged: im.length, resisted: (im as { outcome: string | null }[]).filter((i) => i.outcome === "resisted").length, by_kind: byKind },
    finance: { entries: fin.length, days_with_entries: new Set(fin.map((f) => f.entry_date)).size, discretionary_total: fin.filter((f) => f.discretionary).reduce((a, f) => a + Number(f.amount), 0), spent_total: fin.filter((f) => f.kind === "expense").reduce((a, f) => a + Number(f.amount), 0) },
    goals: { active: goals.length, progress_entries: gp.length },
    checkins: { morning: sess.filter((x) => x.kind === "morning" && x.status === "completed").length, midday: sess.filter((x) => x.kind === "midday" && x.status === "completed").length, evening: sess.filter((x) => x.kind === "evening" && x.status === "completed").length, skipped_answers: answers.filter((a) => a.skipped).length },
    journal: { entries: je.length, avg_mood: moods.length ? Math.round((moods.reduce((a, b) => a + b, 0) / moods.length) * 10) / 10 : null, tags },
    distraction_reports: answers.filter((a) => (a.question_key === "distraction_minutes" || a.question_key === "distracted_by") && !a.skipped && a.answer).map((a) => a.answer).slice(0, 7),
  };

  const matched: Example[] = [
    ...C.filter((c) => c.status === "kept" && c.verification === "evidence").map((c) => ({ date: c.commitment_date, text: `Kept “${c.title}” on time${c.evidence ? ` — ${c.evidence}` : ""}`, source: "commitment" })),
    ...C.filter((c) => c.status === "kept" && c.verification !== "evidence").map((c) => ({ date: c.commitment_date, text: `Kept “${c.title}” on time (self-reported)`, source: "commitment" })),
    ...Ts.filter((t) => t.status === "done" && t.verification === "evidence").map((t) => ({ date: t.scheduled_for, text: `Finished “${t.title}” with evidence`, source: "task" })),
    ...(metrics.impulses.resisted ? [{ date: end, text: `Resisted ${metrics.impulses.resisted} of ${metrics.impulses.logged} logged urges`, source: "impulse_logs" }] : []),
    ...(pc.length ? [{ date: end, text: `Confirmed ${pc.length} of 35 prayers`, source: "prayer" }] : []),
  ].slice(0, 8);
  const mismatched: Example[] = [
    ...C.filter((c) => c.status === "broken").map((c) => ({ date: c.commitment_date, text: `Did not keep “${c.title}”${c.failure_context ? ` — before it: ${c.failure_context}` : ""}`, source: "commitment" })),
    ...Ts.filter((t) => t.postponed_count >= 2).map((t) => ({ date: t.scheduled_for, text: `“${t.title}” postponed ${t.postponed_count} times`, source: "task" })),
    ...Ts.filter((t) => t.status === "missed").map((t) => ({ date: t.scheduled_for, text: `Missed “${t.title}”${t.miss_reason ? ` — ${t.miss_reason}` : ""}`, source: "task" })),
    ...(C.filter((c) => c.status === "open").length ? [{ date: end, text: `${C.filter((c) => c.status === "open").length} commitments were never recorded as kept or not kept`, source: "commitment" }] : []),
  ].slice(0, 8);

  return { metrics, matched, mismatched };
}

export async function narrate(metrics: WeeklyMetrics, matched: Example[], mismatched: Example[]): Promise<{ text: string; priorities: string[]; model: string } | null> {
  const key = env.anthropicKey();
  if (!key) return null;
  const client = new Anthropic({ apiKey: key, timeout: 45_000, maxRetries: 1 });
  const res = await client.messages.create({
    model: env.anthropicModel(), max_tokens: 900,
    system: "You write a short weekly interpretation for a private accountability app. Use ONLY the JSON provided. State the sample sizes when they are small, and say 'not enough data' rather than guessing. No diagnoses, no personality labels, no overall judgment of the person, no motivational quotes. Output JSON: {\"interpretation\": string (<=180 words, plain text), \"priorities\": [three specific, realistic adjustments for next week, each <= 25 words]}.",
    messages: [{ role: "user", content: JSON.stringify({ metrics, matched, mismatched }) }],
  });
  const text = res.content.filter((b): b is Anthropic.TextBlock => b.type === "text").map((b) => b.text).join("");
  try {
    const j = JSON.parse(text.slice(text.indexOf("{"), text.lastIndexOf("}") + 1));
    return { text: String(j.interpretation ?? ""), priorities: (j.priorities ?? []).map(String).slice(0, 3), model: env.anthropicModel() };
  } catch {
    return null;
  }
}

export async function generateWeeklyReport(db: SupabaseClient, userId: string, weekStart: string, tz: string, aiConsent: boolean) {
  const { metrics, matched, mismatched } = await computeWeek(db, userId, weekStart, tz);
  const n = aiConsent ? await narrate(metrics, matched, mismatched).catch(() => null) : null;
  const { data, error } = await db.from("weekly_reports").upsert({
    user_id: userId, week_start: weekStart, period_start: weekStart, period_end: metrics.period.end,
    metrics, sample: metrics.sample, matched, mismatched,
    interpretation: n?.text ?? null, priorities: n?.priorities ?? [], model: n?.model ?? null, generated_at: new Date().toISOString(),
  }, { onConflict: "user_id,week_start" }).select("id").single();
  if (error) throw new Error(error.message);
  return data.id as string;
}
